import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class ConcurrentHashMapDemo {
    public static void main(String[] args) {
        ConcurrentMap<String, String> map = new ConcurrentHashMap<>();

        // Atomically computes a value if the key is absent (uses Java 8+ CAS/synchronized bin locking)
        map.computeIfAbsent("databaseUrl", k -> {
            System.out.println("Computing value for: " + k);
            return "jdbc:postgresql://localhost:5432/production";
        });

        // Thread-safe concurrent update
        map.merge("databaseUrl", "?ssl=true", (oldVal, newVal) -> oldVal + newVal);

        System.out.println(map.get("databaseUrl"));
    }
}
